select partition_date, case when rnk in(1, 2) or checkpoint_partition <=(nth_value(checkpoint_partition, 2) over( order by checkpoint_partition)) + 300 then checkpoint_partition else min(checkpoint_partition) over (partition by partition_date) end as checkpoint_partition , process_date FROM ( SELECT CAST(date_format(process_date, 'yyyyMMdd') AS long) AS partition_date, checkpoint_partition, DENSE_RANK() OVER ( ORDER BY checkpoint_partition ASC) as rnk, process_date FROM ( SELECT DISTINCT partition_minute AS checkpoint_partition , now() AS process_date FROM tb_landing_ss_esim WHERE partition_minute < bigint(date_format(now()-INTERVAL 5 MINUTE, 'yyyyMMddHHmm')) AND partition_minute >= ( SELECT COALESCE(MAX(checkpoint_partition), 0) AS checkpoint_partition FROM tb_staging_ss_esim_checkpoint) AND TRUE = COALESCE(( SELECT success FROM tb_staging_ss_esim_landing_to_discovery_workflow_status), TRUE)))